use std::{cell::RefCell, collections::{HashMap, HashSet}};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use wasm_bindgen::prelude::*;
use web_sys::{Document, Element, Node};

#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct Application { root_element_id:String, #[serde(default)] revision:Option<String>, elements:Vec<ElementNode>, texts:Vec<TextNode>, #[serde(default)] bindings:Vec<Binding>, #[serde(default)] expressions:Vec<Expression>, #[serde(default)] prop_programs:Vec<PropProgram>, #[serde(default)] events:Vec<EventBinding>, #[serde(default)] loops:Vec<Loop>, #[serde(default)] contexts:Vec<ContextScope>, #[serde(default)] context_definitions:Vec<ContextDefinition>, #[serde(default)] host_element_refs:Vec<HostElementRef> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct ElementNode { id:String, tag:String, #[serde(default)] attributes:Vec<Attribute>, #[serde(default)] children:Vec<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct Attribute { name:String, static_value:Option<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct TextNode { id:String, static_value:Option<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct Binding { #[serde(rename="id")] _id:String, kind:String, target_id:String, attribute_name:Option<String>, expression_id:Option<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct PropProgram { target_id:String, writes:Vec<PropWrite> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct PropWrite { name:String, static_value:Option<String>, expression_id:Option<String>, kind:String }
#[derive(Clone, Deserialize)] struct Expression { id:String, expression:Value }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct EventBinding { #[serde(rename="type")] event_type:String, target_id:String, action_id:String, field:Option<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct Loop { #[serde(rename="id")] _id:String, parent_id:String, input_id:Option<String>, query_id:Option<String>, row_template_root_element_id:Option<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct ContextScope { id:String, context_id:String, value_expression_id:Option<String>, #[serde(default)] children:Vec<String> }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct ContextDefinition { id:String, default_expression_id:String }
#[derive(Clone, Deserialize)] #[serde(rename_all="camelCase")]
struct HostElementRef { id:String, target_id:String, #[serde(default)] attachments:Vec<String> }
#[derive(Deserialize)] #[serde(tag="type", rename_all="camelCase")]
enum Delta { Update { input_id:String, row_key:String, changes:HashMap<String,Value> }, Insert { input_id:String, row_key:String, row:HashMap<String,Value>, before_row_key:Option<String> }, Remove { input_id:String, row_key:String }, Move { input_id:String, row_key:String, before_row_key:Option<String> } }
#[derive(Default, Serialize, Deserialize)] #[serde(rename_all="camelCase")]
struct UpdateMetrics { dom_operations:u32, nodes_touched:u32, bindings_touched:u32, wasm_dom_us:f64 }
#[derive(Default, Serialize)] #[serde(rename_all="camelCase")]
struct MountMetrics { decode_us:f64, static_mount_us:f64, row_program_execute_us:f64, row_state_registration_us:f64, fragment_append_us:f64, program_compile_us:f64, program_revision:Option<String>, instruction_count:u32, compiled_expression_count:u32, field_slot_count:u32, binding_program_count:u32, average_row_program_execute_us:f64, row_count:u32, created_elements:u32, created_texts:u32, bindings:u32, dom_operations:u32 }
struct Row { root:Node, values:HashMap<String,Value>, nodes:HashMap<String,Node> }

#[wasm_bindgen]
pub struct Runtime { application:RefCell<Option<Application>>, mounted:RefCell<HashMap<String,Node>>, host_refs:RefCell<HashMap<String,Node>>, rows:RefCell<HashMap<String,HashMap<String,Row>>> }
#[wasm_bindgen]
impl Runtime {
 #[wasm_bindgen(constructor)] pub fn new()->Runtime { Runtime { application:RefCell::new(None), mounted:RefCell::new(HashMap::new()), host_refs:RefCell::new(HashMap::new()), rows:RefCell::new(HashMap::new()) } }
 pub fn load_application(&self, ir:JsValue)->Result<(),JsValue>{ self.application.replace(Some(serde_wasm_bindgen::from_value(ir).map_err(error)?)); Ok(()) }
 pub fn mount(&self, root:Element)->Result<JsValue,JsValue>{
  let app=self.app()?; let doc=document()?; let elements=index_elements(&app); let texts=index_texts(&app); let mut nodes=HashMap::new();
  let contexts=index_contexts(&app); let environment=context_defaults(&app); let root_node=instantiate(&doc,&app.root_element_id,&elements,&texts,&contexts,&app.bindings,&app.prop_programs,&app.expressions,&app.events,&HashMap::new(),&environment,&mut nodes)?;
  root.set_inner_html(""); root.append_child(&root_node)?; let mut handles=HashMap::new(); for reference in &app.host_element_refs { if let Some(node)=nodes.get(&reference.target_id) { for attachment in &reference.attachments { handles.insert(attachment.clone(),node.clone()); } handles.insert(reference.id.clone(),node.clone()); } } self.mounted.replace(nodes); self.host_refs.replace(handles); self.rows.replace(HashMap::new());
  finish(MountMetrics{program_revision:app.revision.clone(),created_elements:app.elements.len() as u32,created_texts:app.texts.len() as u32,bindings:app.bindings.len() as u32,dom_operations:1,..Default::default()})
 }
 pub fn adopt(&self, _root:Element)->Result<JsValue,JsValue>{ serde_wasm_bindgen::to_value(&Option::<MountMetrics>::None).map_err(error) }
 pub fn dispose(&self)->Result<(),JsValue>{ self.rows.borrow_mut().clear(); self.host_refs.borrow_mut().clear(); self.mounted.borrow_mut().clear(); self.application.borrow_mut().take(); Ok(()) }
 pub fn initialize_input(&self,input_id:String,rows:JsValue)->Result<JsValue,JsValue>{
  let values:Vec<HashMap<String,Value>>=serde_wasm_bindgen::from_value(rows).map_err(error)?; let app=self.app()?; let loop_node=find_loop(&app,&input_id)?; let parent=self.mounted.borrow().get(&loop_node.parent_id).cloned().ok_or_else(||JsValue::from_str("loop parent missing"))?; let parent:Element=parent.dyn_into().map_err(|_|JsValue::from_str("loop parent"))?; let root_id=loop_node.row_template_root_element_id.ok_or_else(||JsValue::from_str("row template missing"))?; let doc=document()?; let elements=index_elements(&app); let texts=index_texts(&app); let fragment=doc.create_document_fragment(); let mut collected=HashMap::new();
  let contexts=index_contexts(&app); let environment=context_defaults(&app); for value in values { let key=value_string(value.get("id")); let mut nodes=HashMap::new(); let row_root=instantiate(&doc,&root_id,&elements,&texts,&contexts,&app.bindings,&app.prop_programs,&app.expressions,&app.events,&value,&environment,&mut nodes)?; if let Ok(element)=row_root.clone().dyn_into::<Element>() { element.set_attribute("data-runtime-row-key",&key)?; } fragment.append_child(&row_root)?; collected.insert(key,Row{root:row_root,values:value,nodes}); }
  parent.append_child(&fragment)?; let count=collected.len() as u32; self.rows.borrow_mut().insert(input_id,collected); finish(MountMetrics{row_count:count,dom_operations:1,..Default::default()})
 }
 pub fn apply_delta(&self, delta:JsValue)->Result<JsValue,JsValue>{ let start=now(); let delta:Delta=serde_wasm_bindgen::from_value(delta).map_err(error)?; let mut metrics=UpdateMetrics::default(); match delta { Delta::Update{input_id,row_key,changes}=>self.update(&input_id,&row_key,changes,&mut metrics)?, Delta::Insert{input_id,row_key,row,before_row_key}=>self.insert(&input_id,row_key,row,before_row_key,&mut metrics)?, Delta::Remove{input_id,row_key}=>self.remove(&input_id,&row_key,&mut metrics)?, Delta::Move{input_id,row_key,before_row_key}=>self.move_row(&input_id,&row_key,before_row_key,&mut metrics)? }; metrics.wasm_dom_us=(now()-start)*1000.0; serde_wasm_bindgen::to_value(&metrics).map_err(error) }
 pub fn apply_deltas(&self,deltas:JsValue)->Result<JsValue,JsValue>{ let values:Vec<Value>=serde_wasm_bindgen::from_value(deltas).map_err(error)?; let mut total=UpdateMetrics::default(); for value in values { let result:UpdateMetrics=serde_wasm_bindgen::from_value(self.apply_delta(serde_wasm_bindgen::to_value(&value).map_err(error)?)?).map_err(error)?; total.dom_operations+=result.dom_operations; total.nodes_touched+=result.nodes_touched; total.bindings_touched+=result.bindings_touched; total.wasm_dom_us+=result.wasm_dom_us; } serde_wasm_bindgen::to_value(&total).map_err(error) }
}
impl Runtime {
 fn app(&self)->Result<Application,JsValue>{self.application.borrow().clone().ok_or_else(||JsValue::from_str("load_application must be called first"))}
 fn update(&self,input:&str,key:&str,changes:HashMap<String,Value>,m:&mut UpdateMetrics)->Result<(),JsValue>{ let app=self.app()?; let changed=changes.keys().cloned().collect::<HashSet<_>>(); let expressions=app.expressions.iter().map(|entry|(entry.id.as_str(),&entry.expression)).collect::<HashMap<_,_>>(); let mut rows=self.rows.borrow_mut(); let row=rows.get_mut(input).and_then(|items|items.get_mut(key)).ok_or_else(||JsValue::from_str("row missing"))?; row.values.extend(changes); for binding in &app.bindings { if !binding_dependencies(binding,&expressions).iter().any(|field|changed.contains(field)) { continue; } if let Some(node)=row.nodes.get(&binding.target_id) { apply_binding(node,binding,&app.expressions,&row.values)?; m.bindings_touched+=1; m.nodes_touched+=1; m.dom_operations+=1; } } for program in &app.prop_programs { if !program_dependencies(program,&expressions).iter().any(|field|changed.contains(field)) { continue; } if let Some(node)=row.nodes.get(&program.target_id) { apply_prop_program(node,program,&app.expressions,&row.values)?; m.nodes_touched+=1; m.dom_operations+=1; } } Ok(()) }
 fn insert(&self,input:&str,key:String,value:HashMap<String,Value>,before:Option<String>,m:&mut UpdateMetrics)->Result<(),JsValue>{ let app=self.app()?; let loop_node=find_loop(&app,input)?; let parent=self.mounted.borrow().get(&loop_node.parent_id).cloned().ok_or_else(||JsValue::from_str("loop parent missing"))?; let parent:Element=parent.dyn_into().map_err(|_|JsValue::from_str("loop parent"))?; let doc=document()?; let mut nodes=HashMap::new(); let elements=index_elements(&app); let texts=index_texts(&app); let contexts=index_contexts(&app); let environment=context_defaults(&app); let root=instantiate(&doc,&loop_node.row_template_root_element_id.ok_or_else(||JsValue::from_str("row template missing"))?,&elements,&texts,&contexts,&app.bindings,&app.prop_programs,&app.expressions,&app.events,&value,&environment,&mut nodes)?; if let Ok(element)=root.clone().dyn_into::<Element>(){element.set_attribute("data-runtime-row-key",&key)?;} let anchor=before.and_then(|id|self.rows.borrow().get(input).and_then(|rows|rows.get(&id)).map(|row|row.root.clone())); parent.insert_before(&root,anchor.as_ref())?; self.rows.borrow_mut().entry(input.into()).or_default().insert(key,Row{root,values:value,nodes});m.dom_operations+=1;Ok(()) }
 fn remove(&self,input:&str,key:&str,m:&mut UpdateMetrics)->Result<(),JsValue>{if let Some(row)=self.rows.borrow_mut().get_mut(input).and_then(|rows|rows.remove(key)){row.root.parent_node().map(|parent|parent.remove_child(&row.root)).transpose()?;m.dom_operations+=1;}Ok(())}
 fn move_row(&self,input:&str,key:&str,before:Option<String>,m:&mut UpdateMetrics)->Result<(),JsValue>{let app=self.app()?;let parent:Element=self.mounted.borrow().get(&find_loop(&app,input)?.parent_id).cloned().ok_or_else(||JsValue::from_str("loop parent missing"))?.dyn_into().map_err(|_|JsValue::from_str("loop parent"))?;let row=self.rows.borrow().get(input).and_then(|rows|rows.get(key)).ok_or_else(||JsValue::from_str("row missing"))?.root.clone();let anchor=before.and_then(|id|self.rows.borrow().get(input).and_then(|rows|rows.get(&id)).map(|row|row.root.clone()));parent.insert_before(&row,anchor.as_ref())?;m.dom_operations+=1;Ok(())}
}
fn instantiate(doc:&Document,id:&str,elements:&HashMap<String,ElementNode>,texts:&HashMap<String,TextNode>,contexts:&HashMap<String,ContextScope>,bindings:&[Binding],prop_programs:&[PropProgram],expressions:&[Expression],events:&[EventBinding],scope:&HashMap<String,Value>,environment:&HashMap<String,Value>,nodes:&mut HashMap<String,Node>)->Result<Node,JsValue>{
 if let Some(provider)=contexts.get(id){let fragment:Node=doc.create_document_fragment().into();let mut child_environment=environment.clone();let value=expression_value_with_context(&provider.value_expression_id,expressions,scope,environment);child_environment.insert(provider.context_id.clone(),value);for child in &provider.children{let child=instantiate(doc,child,elements,texts,contexts,bindings,prop_programs,expressions,events,scope,&child_environment,nodes)?;fragment.append_child(&child)?;}return Ok(fragment)}
 if let Some(text)=texts.get(id){let node:Node=doc.create_text_node(text.static_value.as_deref().unwrap_or("")).into();if let Some(binding)=bindings.iter().find(|entry|entry.target_id==id){apply_binding_with_context(&node,binding,expressions,scope,environment)?;}nodes.insert(id.into(),node.clone());return Ok(node)} let element=elements.get(id).ok_or_else(||JsValue::from_str("node missing"))?;let node=doc.create_element(&element.tag)?;node.set_attribute("data-runtime-node",id)?;for attribute in &element.attributes{if let Some(value)=&attribute.static_value{set_value(&node,&attribute.name,&Value::String(value.clone()))?;}}for binding in bindings.iter().filter(|entry|entry.target_id==id){apply_binding_with_context(&node.clone().into(),binding,expressions,scope,environment)?;}for program in prop_programs.iter().filter(|entry|entry.target_id==id){apply_prop_program(&node.clone().into(),program,expressions,scope)?;}for event in events.iter().filter(|entry|entry.target_id==id){node.set_attribute("data-runtime-action",&event.action_id)?;node.set_attribute("data-runtime-event",&event.event_type)?;if let Some(field)=&event.field{node.set_attribute("data-runtime-field",field)?;}}for child in &element.children{let child=instantiate(doc,child,elements,texts,contexts,bindings,prop_programs,expressions,events,scope,environment,nodes)?;node.append_child(&child)?;}let node:Node=node.into();nodes.insert(id.into(),node.clone());Ok(node)
}
fn apply_binding_with_context(node:&Node,binding:&Binding,expressions:&[Expression],scope:&HashMap<String,Value>,environment:&HashMap<String,Value>)->Result<(),JsValue>{let value=binding.expression_id.as_ref().and_then(|id|expressions.iter().find(|entry|entry.id==*id)).map(|entry|evaluate_with_context(&entry.expression,scope,environment)).unwrap_or(Value::Null);if binding.kind=="text"{node.clone().dyn_into::<web_sys::Text>().map_err(|_|JsValue::from_str("text binding target"))?.set_data(&value_string(Some(&value)));}else{let element:Element=node.clone().dyn_into().map_err(|_|JsValue::from_str("element binding target"))?;set_value(&element,binding.attribute_name.as_deref().unwrap_or_default(),&value)?;}Ok(())}
fn expression_value_with_context(id:&Option<String>,expressions:&[Expression],scope:&HashMap<String,Value>,environment:&HashMap<String,Value>)->Value{id.as_ref().and_then(|id|expressions.iter().find(|entry|entry.id==*id)).map(|entry|evaluate_with_context(&entry.expression,scope,environment)).unwrap_or(Value::Null)}
fn apply_binding(node:&Node,binding:&Binding,expressions:&[Expression],scope:&HashMap<String,Value>)->Result<(),JsValue>{let value=expressions.iter().find(|entry|Some(&entry.id)==binding.expression_id.as_ref()).map(|entry|evaluate(&entry.expression,scope)).unwrap_or(Value::Null);if binding.kind=="text"{node.clone().dyn_into::<web_sys::Text>().map_err(|_|JsValue::from_str("text binding target"))?.set_data(&value_string(Some(&value)));}else{let element:Element=node.clone().dyn_into().map_err(|_|JsValue::from_str("element binding target"))?;set_value(&element,binding.attribute_name.as_deref().unwrap_or_default(),&value)?;}Ok(())}
fn expression_value(id:&Option<String>,expressions:&[Expression],scope:&HashMap<String,Value>)->Value{ id.as_ref().and_then(|id|expressions.iter().find(|entry|entry.id==*id)).map(|entry|evaluate(&entry.expression,scope)).unwrap_or(Value::Null) }
fn apply_prop_program(node:&Node,program:&PropProgram,expressions:&[Expression],scope:&HashMap<String,Value>)->Result<(),JsValue>{let element:Element=node.clone().dyn_into().map_err(|_|JsValue::from_str("prop program target"))?;for write in &program.writes{if write.kind=="event"||write.kind=="ref"{continue}if write.kind=="spread"{let value=expression_value(&write.expression_id,expressions,scope);let Some(record)=value.as_object()else{return Err(JsValue::from_str("runtime spread must evaluate to an object"))};for (name,value) in record{if name=="children"{return Err(JsValue::from_str("runtime spread children are unsupported"))}if name.starts_with("on"){return Err(JsValue::from_str("runtime spread event handlers must be extracted by the compiler"))}set_value(&element,name,value)?;}continue}let value=write.static_value.as_ref().map(|value|Value::String(value.clone())).unwrap_or_else(||expression_value(&write.expression_id,expressions,scope));set_value(&element,&write.name,&value)?;}Ok(())}
fn program_dependencies(program:&PropProgram,expressions:&HashMap<&str,&Value>)->HashSet<String>{let mut fields=HashSet::new();for write in &program.writes{if let Some(id)=write.expression_id.as_deref(){if let Some(expression)=expressions.get(id){collect_dependencies(expression,&mut fields);}}}fields}
fn set_value(element:&Element,name:&str,value:&Value)->Result<(),JsValue>{let name=if name=="className"{"class"}else{name};if name=="checked"{if let Ok(input)=element.clone().dyn_into::<web_sys::HtmlInputElement>(){input.set_checked(value.as_bool().unwrap_or(false));return Ok(())}}if name=="indeterminate"{if let Ok(input)=element.clone().dyn_into::<web_sys::HtmlInputElement>(){input.set_indeterminate(value.as_bool().unwrap_or(false));return Ok(())}}if name=="value"{if let Ok(input)=element.clone().dyn_into::<web_sys::HtmlInputElement>(){input.set_value(&value_string(Some(value)));return Ok(())}}if value.as_bool()==Some(false)||value.is_null(){element.remove_attribute(name)?;}else{element.set_attribute(name,&value_string(Some(value)))?;}Ok(())}
fn evaluate(expression:&Value,scope:&HashMap<String,Value>)->Value{let Some(kind)=expression.get("kind").and_then(Value::as_str)else{return Value::Null};let left=||evaluate(expression.get("left").unwrap_or(&Value::Null),scope);let right=||evaluate(expression.get("right").unwrap_or(&Value::Null),scope);match kind{"literal"=>expression.get("value").cloned().unwrap_or(Value::Null),"identifier"=>scope.get(expression.get("name").and_then(Value::as_str).unwrap_or_default()).cloned().unwrap_or(Value::Null),"member"=>evaluate(expression.get("object").unwrap_or(&Value::Null),scope).get(expression.get("property").and_then(Value::as_str).unwrap_or_default()).cloned().unwrap_or(Value::Null),"conditional"=>if truthy(&evaluate(expression.get("test").unwrap_or(&Value::Null),scope)){evaluate(expression.get("consequent").unwrap_or(&Value::Null),scope)}else{evaluate(expression.get("alternate").unwrap_or(&Value::Null),scope)},"logical"=>{let value=left();match expression.get("op").and_then(Value::as_str){Some("&&")=>if truthy(&value){right()}else{value},Some("||")=>if truthy(&value){value}else{right()},Some("??")=>if value.is_null(){right()}else{value},_=>Value::Null}},"unary"=>{let value=evaluate(expression.get("argument").unwrap_or(&Value::Null),scope);match expression.get("op").and_then(Value::as_str){Some("!")=>Value::Bool(!truthy(&value)),Some("-")=>number(-value.as_f64().unwrap_or(0.0)),Some("+")=>number(value.as_f64().unwrap_or(0.0)),_=>Value::Null}},"binary"=>{let a=left();let b=right();match expression.get("op").and_then(Value::as_str){Some("+")=>if a.is_string()||b.is_string(){Value::String(format!("{}{}",value_string(Some(&a)),value_string(Some(&b))))}else{number(a.as_f64().unwrap_or(0.0)+b.as_f64().unwrap_or(0.0))},Some("-")=>number(a.as_f64().unwrap_or(0.0)-b.as_f64().unwrap_or(0.0)),Some("*")=>number(a.as_f64().unwrap_or(0.0)*b.as_f64().unwrap_or(0.0)),Some("/")=>number(a.as_f64().unwrap_or(0.0)/b.as_f64().unwrap_or(0.0)),Some("%")=>number(a.as_f64().unwrap_or(0.0)%b.as_f64().unwrap_or(0.0)),Some("!==")=>Value::Bool(a!=b),Some("==")|Some("===")=>Value::Bool(a==b),Some("!=")=>Value::Bool(a!=b),Some(">")=>Value::Bool(a.as_f64()>b.as_f64()),Some(">=")=>Value::Bool(a.as_f64()>=b.as_f64()),Some("<")=>Value::Bool(a.as_f64()<b.as_f64()),Some("<=")=>Value::Bool(a.as_f64()<=b.as_f64()),_=>Value::Null}},"template"=>Value::String(expression.get("parts").and_then(Value::as_array).map(|parts|parts.iter().map(|part|if part.is_string(){part.as_str().unwrap_or_default().into()}else{value_string(Some(&evaluate(part,scope)))}).collect()).unwrap_or_default()),"array"=>Value::Array(expression.get("items").and_then(Value::as_array).map(|items|items.iter().map(|item|evaluate(item,scope)).collect()).unwrap_or_default()),"object"=>{let mut result=serde_json::Map::new();let properties=expression.get("properties").and_then(Value::as_array).cloned().unwrap_or_else(||expression.get("entries").and_then(Value::as_array).cloned().unwrap_or_default());for property in properties{match property.get("kind").and_then(Value::as_str){Some("spread")=>if let Some(object)=evaluate(property.get("value").unwrap_or(&Value::Null),scope).as_object(){for (key,value) in object{result.insert(key.clone(),value.clone());}},Some("entry")=>if let Some(key)=property.get("key").and_then(Value::as_str){result.insert(key.into(),evaluate(property.get("value").unwrap_or(&Value::Null),scope));},_=>if let Some(key)=property.get("key").and_then(Value::as_str){result.insert(key.into(),evaluate(property.get("value").unwrap_or(&Value::Null),scope));}}}Value::Object(result)},"intrinsic"=>Value::String(expression.get("args").and_then(Value::as_array).map(|args|args.iter().map(|arg|evaluate(arg,scope)).filter(|value|truthy(value)).map(|value|value_string(Some(&value))).collect::<Vec<_>>().join(" ")).unwrap_or_default()),_=>Value::Null}}
fn evaluate_with_context(expression:&Value,scope:&HashMap<String,Value>,environment:&HashMap<String,Value>)->Value{fn replace(value:&Value,environment:&HashMap<String,Value>)->Value{if value.get("kind").and_then(Value::as_str)==Some("context"){return serde_json::json!({"kind":"literal","value":environment.get(value.get("contextId").and_then(Value::as_str).unwrap_or_default()).cloned().unwrap_or(Value::Null)})}match value{Value::Array(values)=>Value::Array(values.iter().map(|v|replace(v,environment)).collect()),Value::Object(values)=>Value::Object(values.iter().map(|(k,v)|(k.clone(),replace(v,environment))).collect()),_=>value.clone()}}evaluate(&replace(expression,environment),scope)}
fn number(value:f64)->Value{serde_json::Number::from_f64(value).map(Value::Number).unwrap_or(Value::Null)}
fn binding_dependencies(binding:&Binding,expressions:&HashMap<&str,&Value>)->HashSet<String>{let mut fields=HashSet::new();if let Some(expression_id)=binding.expression_id.as_deref(){if let Some(expression)=expressions.get(expression_id){collect_dependencies(expression,&mut fields);}}fields}
fn collect_dependencies(expression:&Value,fields:&mut HashSet<String>){let Some(kind)=expression.get("kind").and_then(Value::as_str)else{return};match kind{"member"=>{let object=expression.get("object").unwrap_or(&Value::Null);if object.get("kind").and_then(Value::as_str)==Some("identifier")&&object.get("name").and_then(Value::as_str)==Some("todo"){if let Some(property)=expression.get("property").and_then(Value::as_str){fields.insert(property.into());}}else{collect_dependencies(object,fields);}},"identifier"=>{if let Some(name)=expression.get("name").and_then(Value::as_str){if name!="todo"{fields.insert(name.into());}}},"unary"=>collect_dependencies(expression.get("argument").unwrap_or(&Value::Null),fields),"conditional"=>{for key in ["test","consequent","alternate"]{collect_dependencies(expression.get(key).unwrap_or(&Value::Null),fields);}},"binary"|"logical"=>{for key in ["left","right"]{collect_dependencies(expression.get(key).unwrap_or(&Value::Null),fields);}},"template"=>{for part in expression.get("parts").and_then(Value::as_array).into_iter().flatten(){collect_dependencies(part,fields);}},"array"|"intrinsic"=>{for item in expression.get("items").or_else(||expression.get("args")).and_then(Value::as_array).into_iter().flatten(){collect_dependencies(item,fields);}},"object"=>{for entry in expression.get("entries").and_then(Value::as_array).into_iter().flatten(){collect_dependencies(entry.get("value").unwrap_or(&Value::Null),fields);}},_=>{}}}
fn index_elements(app:&Application)->HashMap<String,ElementNode>{app.elements.iter().cloned().map(|node|(node.id.clone(),node)).collect()}
fn index_texts(app:&Application)->HashMap<String,TextNode>{app.texts.iter().cloned().map(|node|(node.id.clone(),node)).collect()}
fn index_contexts(app:&Application)->HashMap<String,ContextScope>{app.contexts.iter().cloned().map(|node|(node.id.clone(),node)).collect()}
fn context_defaults(app:&Application)->HashMap<String,Value>{app.context_definitions.iter().map(|definition|(definition.id.clone(),expression_value(&Some(definition.default_expression_id.clone()),&app.expressions,&HashMap::new()))).collect()}
fn find_loop(app:&Application,input:&str)->Result<Loop,JsValue>{app.loops.iter().find(|entry|entry.input_id.as_deref()==Some(input)||entry.query_id.as_deref()==Some(input)).cloned().ok_or_else(||JsValue::from_str("loop missing"))}
fn value_string(value:Option<&Value>)->String{match value.unwrap_or(&Value::Null){Value::String(value)=>value.clone(),Value::Bool(value)=>value.to_string(),Value::Number(value)=>value.to_string(),Value::Null=>String::new(),value=>value.to_string()}}
fn truthy(value:&Value)->bool{!value.is_null()&&value.as_bool()!=Some(false)&&value.as_str()!=Some("")}
fn document()->Result<Document,JsValue>{web_sys::window().ok_or_else(||JsValue::from_str("window unavailable"))?.document().ok_or_else(||JsValue::from_str("document unavailable"))}
fn now()->f64{web_sys::window().and_then(|window|window.performance()).map(|performance|performance.now()).unwrap_or(0.0)}
fn error(error:impl std::fmt::Display)->JsValue{JsValue::from_str(&error.to_string())}
fn finish(metrics:MountMetrics)->Result<JsValue,JsValue>{serde_wasm_bindgen::to_value(&metrics).map_err(error)}

#[cfg(test)]
mod tests {
 use super::*;

 #[test]
 fn collects_only_the_row_fields_used_by_an_expression() {
  let expression=serde_json::json!({"kind":"conditional","test":{"kind":"member","object":{"kind":"identifier","name":"todo"},"property":"done"},"consequent":{"kind":"member","object":{"kind":"identifier","name":"todo"},"property":"title"},"alternate":{"kind":"literal","value":"Open"}});
  let mut fields=HashSet::new();
  collect_dependencies(&expression,&mut fields);
  assert_eq!(fields,HashSet::from(["done".to_owned(),"title".to_owned()]));
 }

 #[test]
 fn evaluates_ordered_record_spreads_and_all_value_primitives() {
  let expression=serde_json::json!({"kind":"object","properties":[
   {"kind":"entry","key":"title","value":{"kind":"template","parts":["Todo: ",{"kind":"member","object":{"kind":"identifier","name":"todo"},"property":"title"}]}},
   {"kind":"spread","value":{"kind":"identifier","name":"todo"}},
   {"kind":"entry","key":"open","value":{"kind":"unary","op":"!","argument":{"kind":"member","object":{"kind":"identifier","name":"todo"},"property":"done"}}}
  ]});
  let scope=HashMap::from([("todo".into(),serde_json::json!({"title":"Overridden","done":false,"rank":2}))]);
  assert_eq!(evaluate(&expression,&scope),serde_json::json!({"title":"Overridden","done":false,"rank":2,"open":true}));
 }

 #[test]
 fn resolves_context_values_from_the_nearest_environment() {
  let expression=serde_json::json!({"kind":"member","object":{"kind":"context","contextId":"theme"},"property":"tone"});
  let outer=HashMap::from([("theme".into(),serde_json::json!({"tone":"outer"}))]);
  let inner=HashMap::from([("theme".into(),serde_json::json!({"tone":"inner"}))]);
  assert_eq!(evaluate_with_context(&expression,&HashMap::new(),&outer),serde_json::json!("outer"));
  assert_eq!(evaluate_with_context(&expression,&HashMap::new(),&inner),serde_json::json!("inner"));
 }
}
